int[] memo = new int[n + 1];
Arrays.fill(memo, -1);          // -1 means not calculated yet

int fib(int n) {
    if (n <= 1) return n;
    if (memo[n] != -1) return memo[n];   // already solved

    memo[n] = fib(n - 1) + fib(n - 2);  // solve and store
    return memo[n];
}

int fib(int n) {
    if (n <= 1) return n;

    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 1;

    for (int i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }

    return dp[n];
}

int fib(int n) {
    if (n <= 1) return n;

    int prev2 = 0, prev1 = 1;

    for (int i = 2; i <= n; i++) {
        int curr = prev1 + prev2;
        prev2 = prev1;
        prev1 = curr;
    }

    return prev1;
}
